WITH Src AS (SELECT *, CAST(unit_price AS INT) AS unit_price_int FROM order_items WHERE unit_price >= 310), OrderIdSummary AS (SELECT order_id, ROUND(STDDEV(quantity), 2) AS stddev_quantity, ROUND(AVG(quantity), 2) AS avg_quantity FROM Src GROUP BY order_id) SELECT order_id, stddev_quantity FROM OrderIdSummary WHERE stddev_quantity < 54 ORDER BY order_id DESC, stddev_quantity DESC;
